    V vertexB = resultMap.get(key + "b");
    E edge = new Edge<>(vertexA, vertexB);
    target.addEdge(edge);
  }

  // Step 4: Add self-loops
  for (String key : resultMap.keySet()) {
    V vertex = resultMap.get(key);
    E edge = new Edge<>(vertex, vertex);
    target.addEdge(edge);
  }
}

