public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
   // Step 1: Get the vertices and edges from the input strings
   List<V> vertices = parseVertices(target);
   List<E> edges = parseEdges(target);

   // Step 2: Create a map to keep track of the vertices and their connections
   Map<V, Set<V>> vertexConnections = new HashMap<>();
   for (V vertex : vertices) {
       vertexConnections.put(vertex, new HashSet<>());
   }

   // Step 3: Iterate over the edges and add them to the graph
   for (E edge : edges) {
       V source = edge.getSource();
       V target = edge.getTarget();
       vertexConnections.get(source).add(target);
       vertexConnections.get(target).add(source);
   }

   // Step 4: Add the vertices and their connections to the graph
   for (Map.Entry<V, Set<V>> entry : vertexConnections.entrySet()) {
       V vertex = entry.getKey();
       Set<V> connections = entry.getValue();
       target.addVertex(vertex);
       for (V connection : connections) {
           target.addEdge(vertex, connection);
       }
   }
}

