public void insertBefore(Bucket bucket) {
    if (bucket != null) {
        if (head == null) {
            head = bucket;
            tail = bucket;
        } else {
            Bucket current = head;
            while (current != null && current != bucket) {
                current = current.next;
            }
            if (current == null) {
                return;
            } else {
                Bucket previous = current.prev;
                current.prev = this;
                this.next = current;
                if (previous != null) {
                    previous.next = this;
                } else {
                    head = this;
                }
            }
        }
    }
}

