    // Check if the bucket is null
    if (bucket == null) {
        throw new IllegalArgumentException("The bucket cannot be null");
    }
    // Check if the bucket is already in the list
    if (this.contains(bucket)) {
        throw new IllegalArgumentException("The bucket is already in the list");
    }
    // Check if the bucket is before this bucket
    if (bucket.getNext() != this) {
        throw new IllegalArgumentException("The bucket is not before this bucket");
    }

    // Link the bucket to the previous node
    bucket.setNext(this.getPrevious());
    // Link the current node to the new bucket
    this.setPrevious(bucket);

    // Update the length of the list
