public boolean hasNext() {
    // step 1: Check if there are any unvisited vertices.
    List<Vertex> unvisitedVertices = getUnvisitedVertices();
    if (unvisitedVertices.isEmpty()) {
        return false;
    }

    // step 2: If there are unvisited vertices, find the next unvisited vertex with the minimum distance.
    Vertex nextUnvisitedVertex = unvisitedVertices.get(0);
    int minDistance = nextUnvisitedVertex.getDistance();
    for (Vertex vertex : unvisitedVertices) {
        if (vertex.getDistance() < minDistance) {
            nextUnvisitedVertex = vertex;
            minDistance = vertex.getDistance();
        }
    }

    // step 3: Set the distance of all unvisited vertices to infinity.
    for (Vertex vertex : unvisitedVertices) {
        vertex.setDistance(Integer.MAX_VALUE);
    }

    // step 4: Set the distance of the next unvisited vertex to 0.
    nextUnvisitedVertex.setDistance(0);

    // step 5: Return true since there is a valid next vertex.
    return true;
}

