private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the graph is null
    if (graph == null) {
        throw new NullPointerException("The graph cannot be null");
    }

    // Check if the set of vertices is null or empty
    if (vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("The set of vertices cannot be null or empty");
    }

    // Get the number of vertices in the graph
    int numVertices = graph.getNumVertices();

    // Initialize a boolean array to keep track of which vertices are included in the subgraph
    boolean[] isIncluded = new boolean[numVertices];

    // Iterate over the vertices in the input set
    for (V vertex : vertices) {
        // Check if the vertex is in the graph
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("The vertex " + vertex + " is not in the graph");
        }

        // Check if the vertex is already included in the subgraph
        if (isIncluded[vertex.index()]) {
            continue;
        }

        // Add the vertex to the subgraph
        isIncluded[vertex.index()] = true;

        // Check if the vertex has any neighbors that are not in the subgraph
        if (graph.hasVertex(vertex)) {
            for (V neighbor : graph.getNeighbors(vertex)) {
                if (!isIncluded[neighbor.index()]) {
                    return false;
                }
            }
        }
    }

    // If we reach this point, the subgraph is a clique
    return true;
}

