    if (vertices.isEmpty()) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }

    // Check if the given set of vertices is null or empty
    if (vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Vertices must not be null or empty");
    }

    // Check if the given set of vertices is a clique
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }

        for (V otherVertex : vertices) {
            if (vertex != otherVertex && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
