public static String stripFilenameExtension(String path){
    // Step 1: Check if the input path is null or empty
    if(path == null || path.isEmpty()){
        return null;
    }

    // Step 2: Define the pattern to match the filename extension
    Pattern pattern = Pattern.compile("\\.[^.]*$");

    // Step 3: Find the last occurrence of the pattern in the path
    Matcher matcher = pattern.matcher(path);
    if(matcher.find()){
        // Step 4: Strip the filename extension from the path
        int startIndex = matcher.start();
        return path.substring(0, startIndex);
    }else{
        // Step 5: If no match is found, return the original path
        return path;
    }
}

public static String stripFilenameExtension(String path) {
  if (path == null) {
    return null;
  }

  int extIndex = path.lastIndexOf(".");
  if (extIndex == -1) {
    return path;
  }

