    // Create a list to store the final components
    List<String> finalComponents = new ArrayList<>();

    // Go through each component of the relative path
    for (String relativeComponent : relativeComponents) {
        // If the component is "..", remove the last component from the final list
        if (relativeComponent.equals("..")) {
            if (!finalComponents.isEmpty()) {
                finalComponents.remove(finalComponents.size() - 1);
            } else {
                throw new IllegalArgumentException("Invalid relative path: " + relativePath);
            }
        // If the component is ".", skip it
        } else if (relativeComponent.equals(".")) {
