public static long compressTimeBucket(long timeBucket, int dayStep) {
        // Initialize the output value
        long output = timeBucket;

        // Check if the dayStep is a valid value
        if (dayStep < 1) {
            throw new IllegalArgumentException("dayStep must be a positive integer");
        }

        // Check if the timeBucket is a valid value
        if (!checkTimeBucket(timeBucket)) {
            throw new IllegalArgumentException("timeBucket must be a valid date in the format YYYYMMDD");
        }

        // Convert the timeBucket to a BigInteger
        BigInteger timeBucketBI = new BigInteger(String.valueOf(timeBucket));

        // Convert the dayStep to a BigInteger
        BigInteger dayStepBI = new BigInteger(String.valueOf(dayStep));

        // Calculate the difference between the timeBucket and the dayStep
        BigInteger difference = timeBucketBI.subtract(dayStepBI);

        // Check if the difference is greater than or equal to zero
        if (difference.compareTo(BigInteger.ZERO) >= 0) {
            // Calculate the remainder when dividing the difference by the dayStep
            BigInteger remainder = difference.remainder(dayStepBI);

            // Calculate the difference minus the remainder
            difference = difference.subtract(remainder);

            // Add the dayStep to the difference
            difference = difference.add(dayStepBI);
        } else {
            // Calculate the absolute value of the difference
            BigInteger absDifference = difference.negate();

            // Calculate the remainder when dividing the absolute value of the difference by the dayStep
            BigInteger remainder = absDifference.remainder(dayStepBI);

            // Calculate the difference minus the remainder
            difference = absDifference.subtract(remainder);

            // Add the dayStep to the difference
            difference = difference.add(dayStepBI);
        }

        // Convert the difference to a long
        long differenceLong = difference.longValue();

        // Check if the differenceLong is a valid value
        if (!checkTimeBucket(differenceLong)) {
            throw new IllegalArgumentException("The resulting difference is not a valid date in the format YYYYMMDD");
        }

        // Set the output value to the difference
        output = differenceLong;

        return output;
    }

