    long endOfDay = timeBucket / 100 * 100 + 99;

    // Step 3: Calculate the number of days to be compressed
    long numDays = dayStep;
    if (numDays % 2 == 0) {
        numDays -= 1;
    }

    // Step 4: Calculate the start of the compressed time bucket
    long startOfCompressedTimeBucket = endOfDay - numDays;

    // Step 5: Return the compressed time bucket
    return startOfCompressedTimeBucket;
