            int endIndex = i + 1;
            while (endIndex < descriptor.length() && descriptor.charAt(endIndex) != ';') {
                endIndex++;
            }
            int size = parseReferenceType(descriptor.substring(i + 1, endIndex));
            numAbstractTypes += size;
            i = endIndex;
        } else if (c == '[') {
            // This is an array type. We need to parse it to determine its size.
            int endIndex = i + 1;
            while (endIndex < descriptor.length() && descriptor.charAt(endIndex) != ')') {
                endIndex++;
            }
            int size = parseArrayType(descriptor.substring(i + 1, endIndex));
            numAbstractTypes += size;
            i = endIndex;
        } else if (c == 'B' || c == 'C' || c == 'D' || c == 'F' || c == 'I' || c == 'J' || c == 'S' || c == 'Z') {
