private void pop(final String descriptor) {
    int stackSize = getStackSize();
    if (stackSize == 0) {
        throw new IllegalStateException("Stack underflow!");
    }

    int descriptorSize = getDescriptorSize(descriptor);
    if (descriptorSize > stackSize) {
        throw new IllegalArgumentException("Descriptor size is larger than stack size!");
    }

    for (int i = 0; i < descriptorSize; i++) {
        pop();
    }
}

