        throw new IllegalArgumentException("Desired capacity must be non-negative");
    }
    if (desiredCapacity < 2) {
        return 2;
    }
    if (desiredCapacity > (1 << 30)) {
        throw new IllegalArgumentException("Desired capacity is too large");
    }
    double capacity = Math.ceil(desiredCapacity / 10);
    boolean isPrime = isPrime(capacity);
    while (!isPrime) {
        capacity += 1;
        isPrime = isPrime(capacity);
    }
    if (capacity - desiredCapacity > desiredCapacity * 0.11) {
        capacity = Math.floor(desiredCapacity / 10) + 1;
