    if (desiredCapacity < 2) {
        return 2;
    }
    if (desiredCapacity == 2) {
        return 3;
    }

    // Start with the next odd number above the desired capacity
    int prime = (desiredCapacity + 1) | 1;

    // Loop until we find a prime number
    while (true) {
        // Check if the number is prime
        boolean isPrime = true;
        for (int i = 3; i * i <= prime; i += 2) {
            if (prime % i == 0) {
                isPrime = false;
                break;
            }
        }

        // If the number is prime, return it
        if (isPrime) {
            return prime;
