  try {
    tag = readRawVarint32();
  } catch (EOFException eof) {
    // If we reached EOF, reset to zero.
    tag = 0;
  }
  return tag;
}

public int readTag() throws IOException {
    if (mInput == null) {
        return 0;
    }
    if (mInput.available() == 0) {
        return 0;
    }
    mEndOfInput.clear();
    int tag = 0;
    try {
        tag = mInput.read();
    } catch (IOException e) {
        throw e;
    }
    if (tag == -1) {
        mEndOfInput.set(TRUE);
        return 0;
    }
    return tag;
}

public int readTag() throws IOException {
    if (isAtEndOfStream()) {
        return 0;
    }
    int tag = read();
    if (tag == 0) {
        throw new ProtocolBufferException("Zero is not a valid tag number");
    }
    return tag;
}

public int readTag() throws IOException {
    if (isAtEnd()) {
        return 0;
    }
    int tag = readRawVarint32();
    if (tag == 0) {
        throw InvalidProtocolBufferException.invalidTag();
    }
    return tag;
}

public int readTag() throws IOException {
    int tag = 0;
    try {
        tag = this.in.readByte() & 0xFF;
    } catch (EOFException e) {
        // do nothing, return default value
    }
    return tag;
}

